const data = $input.first().json || {};
const workflowName = "Seoul Picks - Ranking Publish Hourly";
const blogName = "Seoul Picks 랭킹";
const blogType = "seoul";
const blogBaseUrl = "https://seoul-picks.blogspot.com";
const quietStartHour = 23;
const quietEndHour = 9;

function compact(value, fallback = '') {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object') return JSON.stringify(value).replace(/\s+/g, ' ').trim();
  return String(value).replace(/\s+/g, ' ').trim();
}

function clip(value, limit = 260) {
  const text = compact(value);
  if (!text) return '';
  return text.length > limit ? text.slice(0, limit - 1).trimEnd() + '…' : text;
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function firstText(values, fallback = '') {
  for (const value of values) {
    const text = compact(value);
    if (text) return text;
  }
  return fallback;
}

function formatScore(value) {
  if (value === undefined || value === null || value === '') return '';
  const number = Number(value);
  if (Number.isFinite(number)) return number.toFixed(1).replace(/\.0$/, '') + '점';
  const text = compact(value);
  return text.includes('점') ? text : text + '점';
}

function alertLineValue(label) {
  const alert = String(data.alert || '');
  const match = alert.match(new RegExp('^' + label + ':\\s*(.+)$', 'm'));
  return match ? compact(match[1]) : '';
}

function filename(path) {
  return compact(path).split('/').pop().replace(/\.md$/i, '');
}

function titleFromPath(path) {
  const slug = filename(path).replace(/^\d{4}-\d{2}-\d{2}-/, '');
  return slug ? slug.replace(/-/g, ' ') : '';
}

function gnosysUrl(path) {
  const text = compact(path);
  if (!text) return '';
  if (/^https?:\/\//i.test(text)) return text;
  const slug = filename(text);
  return slug ? blogBaseUrl.replace(/\/$/, '') + '/posts/' + slug + '/' : '';
}

function cleanUrl(url) {
  return compact(url).replace(/[\]})>,.]+$/g, '');
}

function collectUrls(value, out = []) {
  if (value === undefined || value === null) return out;
  if (typeof value === 'string') {
    const matches = value.match(/https?:\/\/[^\s"'<>]+/g) || [];
    for (const match of matches) {
      const url = cleanUrl(match);
      if (url && !out.includes(url)) out.push(url);
    }
    return out;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectUrls(item, out);
    return out;
  }
  if (typeof value === 'object') {
    for (const item of Object.values(value)) collectUrls(item, out);
  }
  return out;
}

function preferredBlogspotUrl() {
  return collectUrls(data).find((url) => url.includes('seoul-picks.blogspot.com')) || '';
}

function alertPosts() {
  const posts = [];
  let current = null;
  for (const rawLine of String(data.alert || '').split('\n')) {
    const line = rawLine.trim();
    const title = line.match(/^\d+\.\s+(.+)$/);
    if (title) {
      if (current) posts.push(current);
      current = { title: compact(title[1]) };
      continue;
    }
    if (!current) continue;
    const summary = line.match(/^요약:\s*(.+)$/);
    const file = line.match(/^파일:\s*(.+)$/);
    if (summary) current.summary = compact(summary[1]);
    if (file) current.path = compact(file[1]);
  }
  if (current) posts.push(current);
  return posts;
}

function writerPosts() {
  const writer = data.writer || {};
  const topics = asArray(writer.topics);
  const selected = asArray(writer.selected);
  const revisions = asArray(writer.revisionCandidates);
  const picked = selected.length ? selected : revisions;
  return picked.map((item, index) => {
    const topic = topics[index] || topics[0] || {};
    return {
      title: firstText([item.title, topic.title]),
      summary: firstText([item.summary, item.description, topic.summary, topic.description]),
      score: item.score,
      topicScore: item.topicScore !== undefined ? item.topicScore : topic.topic_score,
      source: firstText([item.source, topic.url]),
      path: firstText([item.path, asArray(data.createdFiles)[index]]),
      url: firstText([item.url, item.postUrl]),
    };
  });
}

function filePosts() {
  return asArray(data.createdFiles).map((path) => ({
    title: titleFromPath(path),
    path,
  }));
}

function allPosts() {
  const posts = writerPosts();
  if (posts.length) return posts;
  const fromAlert = alertPosts();
  if (fromAlert.length) return fromAlert;
  const fromFiles = filePosts();
  if (fromFiles.length) return fromFiles;
  return [{ title: firstText([data.title, alertLineValue('내용'), alertLineValue('제목')], '제목 확인 필요') }];
}

function postUrl(post) {
  const direct = firstText([post.url, data.url, data.post && data.post.url]);
  if (direct && /^https?:\/\//i.test(direct)) return direct;
  if (blogType === 'gnosys') return gnosysUrl(post.path || asArray(data.createdFiles)[0]);
  if (blogType === 'seoul') return preferredBlogspotUrl();
  return '';
}

function scoreText(post) {
  const parts = [];
  const main = formatScore(post.score !== undefined ? post.score : data.score);
  if (main) parts.push(main);
  const topic = formatScore(post.topicScore !== undefined ? post.topicScore : data.topicScore);
  if (topic) parts.push('주제 ' + topic);
  if (parts.length) return parts.join(' / ');
  const fromAlert = alertLineValue('점수');
  if (fromAlert && !fromAlert.includes('없음') && !fromAlert.includes('수집')) return fromAlert;
  return '';
}

function summaryText(posts) {
  const summaries = [];
  for (const [index, post] of posts.entries()) {
    const text = clip(post.summary || post.description, posts.length > 1 ? 180 : 260);
    if (text) summaries.push(posts.length > 1 ? `${index + 1}. ${text}` : text);
  }
  if (summaries.length) return summaries.join('\n');
  const fallback = firstText([
    alertLineValue('요약'),
    asArray(data.writer && data.writer.topics)[0] && asArray(data.writer && data.writer.topics)[0].summary,
  ]);
  return clip(fallback, 260);
}

function failingStep() {
  const failed = asArray(data.steps).find((step) => Number(step.exitCode) !== 0);
  return firstText([data.failedStep, data.step, failed && failed.name], '확인 필요');
}

function errorText() {
  const failed = asArray(data.steps).find((step) => Number(step.exitCode) !== 0) || {};
  const candidates = [
    data.error && data.error.message,
    data.error,
    data.message,
    data.description,
    alertLineValue('오류'),
    failed.stderrTail,
    failed.stdoutTail,
    data.statusMessage,
  ];
  for (const value of candidates) {
    const text = clip(value, 320);
    if (text) return text;
  }
  return 'runner 응답이 생성되기 전에 실패했습니다.';
}

function kstHour() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Seoul',
    hour: '2-digit',
    hour12: false,
  }).formatToParts(new Date());
  const raw = Number(parts.find((part) => part.type === 'hour')?.value || '0');
  return raw === 24 ? 0 : raw;
}

const ok = data.ok === true;
const collectOnly = data.collectOnly === true;
const hour = kstHour();
const quietHours = hour >= quietStartHour || hour < quietEndHour;
const shouldNotify = !quietHours && !(ok && collectOnly);

if (ok && collectOnly) {
  const lines = [
    '[n8n] 후보 수집 완료',
    `블로그: ${blogName}`,
    `후보: ${data.candidateCount ?? '확인 필요'}개`,
  ];
  return [{ json: { ...data, alert: lines.join('\n'), shouldNotify, quietHours, quietWindow: '23:00-08:59 KST' } }];
}

if (!ok) {
  const lines = [
    '[n8n] 발행 실패',
    `블로그: ${blogName}`,
    `작업: ${workflowName}`,
    `단계: ${failingStep()}`,
    `오류: ${errorText()}`,
  ];
  return [{ json: { ...data, alert: lines.join('\n'), shouldNotify, quietHours, quietWindow: '23:00-08:59 KST' } }];
}

const posts = allPosts();
const titleLines = posts.map((post, index) => `${index + 1}. ${clip(post.title || titleFromPath(post.path), 120)}`).join('\n');
const score = scoreText(posts[0]);
const summary = summaryText(posts);
const links = posts.map(postUrl).filter(Boolean);
const uniqueLinks = [...new Set(links)];
const lines = [
  '[n8n] 발행 완료',
  `블로그: ${blogName}`,
  '',
  '제목',
  titleLines,
];
if (summary) lines.push('', '요약', summary);
if (score) lines.push('', `점수: ${score}`);
if (uniqueLinks.length) lines.push('', '링크', uniqueLinks.join('\n'));

return [{ json: { ...data, alert: lines.join('\n'), shouldNotify, quietHours, quietWindow: '23:00-08:59 KST' } }];

const data = $input.first().json || {};
if (data.shouldNotify === false) {
  return [];
}
return [{ json: data }];
